# High Power Infrared LED Emitter Module
#
# Hardware---------------------------------------------------------------------
# Model: Adafruit 5639 (2x 940nm IR LEDs with MOSFET driver, STEMMA JST PH 2mm)
# Power Supply: 3.3V - 5V (5V gives more range)
# Interface: digital signal, active high (high = LEDs on), 3.3V logic is fine
# IR TX Carrier: 38KHz (generated by the Pi, the module only switches the LEDs)
# Reference: https://www.adafruit.com/product/5639
#
# Transmission goes through the kernel's gpio-ir-tx driver, which bit-bangs the
# 38 kHz carrier and the mark/space timing, which Python cannot do reliably at
# 13 us per carrier half-period. Enable it once:
#   echo "dtoverlay=gpio-ir-tx,gpio_pin=18" | sudo tee -a /boot/firmware/config.txt
#   sudo reboot
# or, until the next reboot only: sudo dtoverlay gpio-ir-tx gpio_pin=18
# Afterwards /dev/lirc0 is the transmitter (check with: ls /dev/lirc*).
# Don't use pwm-ir-tx: on kernel 6.18 it times frames but never enables PWM0,
# so the pin stays low and nothing is emitted.
#
# Connections------------------------------------------------------------------
# Raspberry Pi GPIO Pinout:
# Standard 40-pin header; GPIO numbers use BCM numbering.
#
# Module Pin    JST PH wire    Pi Physical Pin    Function
# VIN           Red            4                  5V power
# GND           Black          14                 Ground
# SIG           White          12                 GPIO18
# -----------------------------------------------------------------------------
#
# Usage------------------------------------------------------------------------
#   uv run ir-tx/adafruit_5639.py list
#       Show the keys stored in the capture file.
#
#   uv run ir-tx/adafruit_5639.py send "Power ON" [--repeat 1]
#       Transmit one stored key.
#
#   uv run ir-tx/adafruit_5639.py onoff [--hold 10] [--pause 10] [--cycles 1]
#       Send "Power ON", wait --hold seconds, send "Power OFF", wait --pause
#       seconds before the next cycle. --cycles 0 repeats until Ctrl+C.
#
# Keys are read from captures made with ir-rx/df_robot_dfr0094.py (default:
# ir-rx/captures/rotenso_ac_pietro.json, pick another with --captures).
# -----------------------------------------------------------------------------

import argparse
import fcntl
import json
import os
import struct
import sys
import time
from array import array
from datetime import datetime
from pathlib import Path

LIRC_DEVICE = "/dev/lirc0"
CAPTURES = Path(__file__).parent.parent / "ir-rx" / "captures" / "rotenso_ac_pietro.json"
CARRIER_HZ = 38_000
DUTY_CYCLE = 33  # percent; usual for IR remotes
REPEAT_GAP_S = 0.1  # pause between repeats of one key
ON_KEY = "Power ON"
OFF_KEY = "Power OFF"

# linux/lirc.h
LIRC_GET_FEATURES = 0x80046900
LIRC_SET_SEND_CARRIER = 0x40046913
LIRC_SET_SEND_DUTY_CYCLE = 0x40046915
LIRC_CAN_SEND_PULSE = 0x00000002
LIRC_CAN_SET_SEND_CARRIER = 0x00000100
LIRC_CAN_SET_SEND_DUTY_CYCLE = 0x00000200


# Transmitter ------------------------------------------------------------------


class IRTransmitter:
    """Sends mark/space timings through a kernel LIRC transmitter device."""

    def __init__(self, device=LIRC_DEVICE, carrier_hz=CARRIER_HZ, duty_cycle=DUTY_CYCLE):
        self.device = device
        self.carrier_hz = carrier_hz
        self._fd = os.open(device, os.O_WRONLY)
        try:
            features = self._ioctl(LIRC_GET_FEATURES, 0)
            if not features & LIRC_CAN_SEND_PULSE:
                raise OSError(f"{device} cannot transmit (is it a receiver?)")
            if features & LIRC_CAN_SET_SEND_CARRIER:
                self._ioctl(LIRC_SET_SEND_CARRIER, carrier_hz)
            if features & LIRC_CAN_SET_SEND_DUTY_CYCLE:
                self._ioctl(LIRC_SET_SEND_DUTY_CYCLE, duty_cycle)
        except OSError:
            os.close(self._fd)
            raise

    def _ioctl(self, request, value):
        result = fcntl.ioctl(self._fd, request, struct.pack("I", value))
        return struct.unpack("I", result)[0]

    def send(self, raw_us):
        """Transmit alternating mark/space durations (us), starting with a mark.

        Blocks until the frame has been sent.
        """
        # LIRC wants an odd count: the frame must end with a mark.
        pulses = raw_us if len(raw_us) % 2 else raw_us[:-1]
        os.write(self._fd, array("I", pulses).tobytes())

    def close(self):
        os.close(self._fd)


# Captures ---------------------------------------------------------------------


def load_keys(path):
    data = json.loads(path.read_text())
    return data.get("device", path.stem), data.get("carrier_hz", CARRIER_HZ), data["keys"]


def lookup(keys, name):
    if name in keys:
        return keys[name]
    # Case-insensitive fallback so "power on" works from the shell.
    for key, entry in keys.items():
        if key.lower() == name.lower():
            return entry
    raise KeyError(f"key '{name}' not in captures (available: {', '.join(keys)})")


# Modes ------------------------------------------------------------------------


def _log(message):
    print(f"[{datetime.now():%H:%M:%S}] {message}", flush=True)


def transmit(tx, keys, name, repeat):
    entry = lookup(keys, name)
    for i in range(repeat):
        if i:
            time.sleep(REPEAT_GAP_S)
        tx.send(entry["raw_us"])
    _log(f"sent '{name}' ({len(entry['raw_us'])} pulses{f', x{repeat}' if repeat > 1 else ''})")


def run_list(device, keys):
    print(f"{device}: {len(keys)} keys")
    for name, entry in keys.items():
        print(f"  {name:<16} {entry.get('protocol', '?'):<8} {len(entry['raw_us'])} pulses")


def run_onoff(tx, keys, hold, pause, cycles, repeat):
    # Fail before transmitting anything if either key is missing.
    lookup(keys, ON_KEY), lookup(keys, OFF_KEY)
    print(f"On/off sequence via {tx.device}: hold {hold}s, pause {pause}s, "
          f"{'until Ctrl+C' if cycles == 0 else f'{cycles} cycle(s)'}.")
    cycle = 0
    is_on = False
    try:
        while cycles == 0 or cycle < cycles:
            cycle += 1
            _log(f"cycle {cycle}")
            transmit(tx, keys, ON_KEY, repeat)
            is_on = True
            time.sleep(hold)
            transmit(tx, keys, OFF_KEY, repeat)
            is_on = False
            if cycles == 0 or cycle < cycles:
                time.sleep(pause)
    except KeyboardInterrupt:
        # Don't leave the device running when stopped mid-cycle. Only send OFF
        # after an ON: toggle-style remotes use the same frame for both.
        print()
        if is_on:
            transmit(tx, keys, OFF_KEY, repeat)
        raise


def main():
    parser = argparse.ArgumentParser(description="Adafruit 5639 IR LED emitter: replay captured remote keys")
    parser.add_argument("--device", default=LIRC_DEVICE, help="LIRC transmitter device (default: %(default)s)")
    parser.add_argument("--captures", type=Path, default=CAPTURES,
                        help="capture file from ir-rx (default: rotenso_ac_pietro.json)")
    parser.add_argument("--duty", type=int, default=DUTY_CYCLE, help="carrier duty cycle %% (default: %(default)s)")
    sub = parser.add_subparsers(dest="mode", required=True)

    sub.add_parser("list", help="show stored keys")

    send = sub.add_parser("send", help="transmit one stored key")
    send.add_argument("key", help="key name as stored in the capture file")
    send.add_argument("--repeat", type=int, default=1, help="times to send the frame (default: %(default)s)")

    onoff = sub.add_parser("onoff", help=f"send '{ON_KEY}', wait, send '{OFF_KEY}'")
    onoff.add_argument("--hold", type=float, default=10, help="seconds between ON and OFF (default: %(default)s)")
    onoff.add_argument("--pause", type=float, default=10, help="seconds between cycles (default: %(default)s)")
    onoff.add_argument("--cycles", type=int, default=1, help="number of cycles, 0 = forever (default: %(default)s)")
    onoff.add_argument("--repeat", type=int, default=1, help="times to send each frame (default: %(default)s)")

    args = parser.parse_args()
    try:
        device, carrier_hz, keys = load_keys(args.captures)
    except (OSError, ValueError, KeyError) as err:
        print(f"Cannot read captures {args.captures}: {err}", file=sys.stderr)
        return 1
    if args.mode == "list":
        return run_list(device, keys)

    try:
        tx = IRTransmitter(args.device, carrier_hz, args.duty)
    except OSError as err:
        print(f"Cannot open IR transmitter {args.device}: {err}\n"
              f"Enable it with dtoverlay=gpio-ir-tx,gpio_pin=18 in /boot/firmware/config.txt "
              f"and reboot, or for this boot only: sudo dtoverlay gpio-ir-tx gpio_pin=18", file=sys.stderr)
        return 1
    try:
        if args.mode == "send":
            transmit(tx, keys, args.key, args.repeat)
        else:
            run_onoff(tx, keys, args.hold, args.pause, args.cycles, args.repeat)
    except KeyError as err:
        print(err.args[0], file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        pass
    finally:
        tx.close()


if __name__ == "__main__":
    sys.exit(main())
